  assert needle and needle.isascii() and needle==needle.lower() and len(needle)<self.block_chars
  n=self.starts[-1];start=max(0,start if start>=0 else n+start)
  if start>=n:return -1
  i=bisect.bisect_right(self.starts,start)-1
  while i<len(self.starts)-1:
   b=self.block(i);x=b+(self.block(i+1)[:len(needle)-1] if i+1<len(self.starts)-1 else '')
